===== src/gbnf.ts
import { Graph } from './grammar_graph/graph.ts';
import { ParseState } from './grammar_graph/parse_state.ts';
import { buildRuleStack } from './grammar_parser/build_rule_stack.ts';
import { GrammarParseError, RulesBuilder } from './rules_builder/index.ts';

export const GBNF = (grammar: string, initialString = ''): ParseState => {
  if (typeof grammar !== 'string') {
    throw new Error('grammar must be a string');
  }

  if (typeof initialString !== 'string') {
    throw new Error('input must be a string');
  }

  const rulesBuilder = new RulesBuilder(grammar);
  const { rules, symbolIds } = rulesBuilder;
  if (rules.length === 0) {
    throw new GrammarParseError(grammar, 0, 'No rules were found');
  }
  if (symbolIds.get('root') === undefined) {
    throw new GrammarParseError(grammar, 0, "Grammar does not contain a 'root' symbol");
  }
  const rootId: number = symbolIds.get('root') as number;

  const stackedRules = rules.map((rule) => buildRuleStack(rule));
  const graph = new Graph(grammar, stackedRules, rootId);
  return new ParseState(graph, graph.add(initialString));
};

export default GBNF;
===== src/utils/code_point_length.ts
/**
 * The number of code points in a string.
 *
 * JavaScript's `String#length` counts UTF-16 code units, so any character
 * outside the BMP (an emoji, for instance) counts as two. Positions in this
 * library are code point based, so lengths must be counted the same way.
 */
export const codePointLength = (src: string): number => Array.from(src).length;
===== src/utils/validate_non_empty.ts
export const validateNonEmpty = <T>(value: T[]): T[] => {
  if (!value || value.length === 0) {
    throw new Error('Value cannot be empty.');
  }
  return value;
};

export const validate_non_empty = validateNonEmpty;
===== src/utils/is_point_in_range.ts
import type { Range } from '../grammar_graph/grammar_graph_types.ts';

export const isPointInRange = (point: number, givenRange: Range): boolean => {
  if (!Number.isInteger(point)) {
    throw new Error('point must be an integer');
  }
  return point >= givenRange[0] && point <= givenRange[1];
};

export const is_point_in_range = isPointInRange;
===== src/utils/errors/build_error_position.ts
import { codePointLength } from '../code_point_length.ts';

export const MAXIMUM_NUMBER_OF_ERROR_LINES_TO_SHOW = 3;

export const buildErrorPosition = (src: string, pos: number): string[] => {
  if (src === '') {
    return [
      'No input provided',
    ];
  }
  const lines = src.split('\n');

  let lineIdx = 0;
  while (
    lines[lineIdx] &&
    pos > codePointLength(lines[lineIdx]) - 1 &&
    pos < codePointLength(src)
  ) {
    pos -= codePointLength(lines[lineIdx]);
    lineIdx += 1;
  }

  const linesToShow = lines.slice(
    Math.max(0, lineIdx - (MAXIMUM_NUMBER_OF_ERROR_LINES_TO_SHOW - 1)),
    lineIdx + 1,
  );

  return [
    ...linesToShow,
    `${' '.repeat(Math.max(0, pos))}^`,
  ];
};

export const build_error_position = buildErrorPosition;
===== src/utils/errors/errors_types.ts
/**
 * Valid input can either be a string, a number indicating a code point, or a
 * list of code points.
 */
export type ValidInput = string | number | number[];
===== src/utils/errors/get_input_as_string.ts
import type { ValidInput } from './errors_types.ts';

export const getInputAsString = (src: ValidInput): string => {
  if (typeof src === 'string') {
    return src;
  }
  if (typeof src === 'number') {
    return String.fromCodePoint(src);
  }
  return src.map((codePoint) => String.fromCodePoint(codePoint)).join('');
};

export const get_input_as_string = getInputAsString;
===== src/utils/errors/grammar_parse_error.ts
import { buildErrorPosition } from './build_error_position.ts';

export const GRAMMAR_PARSER_ERROR_HEADER_MESSAGE = (reason: string): string =>
  `Failed to parse grammar: ${reason}`;

const buildMessage = (grammar: string, pos: number, reason: string): string => [
  GRAMMAR_PARSER_ERROR_HEADER_MESSAGE(reason),
  '',
  ...buildErrorPosition(grammar, pos),
].join('\n');

export class GrammarParseError extends Error {
  grammar: string;
  pos: number;
  reason: string;

  constructor(grammar: string, pos: number, reason: string) {
    super(buildMessage(grammar, pos, reason));
    this.name = 'GrammarParseError';
    this.grammar = grammar;
    this.pos = pos;
    this.reason = reason;
  }

  toString(): string {
    return buildMessage(this.grammar, this.pos, this.reason);
  }
}
