    this.rule = rule;
    if (meta === undefined || meta === null) {
      throw new Error('Meta is undefined');
    }
    this.meta = meta;
    this.next = nextNode ?? undefined;
  }

  get id(): string {
    if (this.__id__ === undefined) {
      this.__id__ = `${this.meta.stackId},${this.meta.pathId},${this.meta.stepId}`;
