import { Color } from './colorize.ts';
import { getParentStackId } from './get_parent_stack_id.ts';
import { isRange, isRuleChar, isRuleRef } from './type_guards.ts';

import type { PrintOpts } from './grammar_graph_types.ts';
import type { GraphNode } from './graph_node.ts';
import type { GraphPointer } from './graph_pointer.ts';

export const printGraphPointer =
  (pointer: GraphPointer) =>
  (opts: PrintOpts): string => {
    const col = opts.colorize;
    return col(`*${getParentStackId(pointer, col)}`, Color.RED);
  };

export const printGraphNode =
  (node: GraphNode) =>
  (opts: PrintOpts): string => {
    const pointers = opts.pointers ? Array.from(opts.pointers) : [];
    const col = opts.colorize;
    const showPosition = opts.show_position ?? opts.showPosition ?? false;
    const rule = node.rule;
    const parts: string[] = [];
    if (showPosition) {
      parts.push(col('{', Color.BLUE), col(node.id, Color.GRAY), col('}', Color.BLUE));
    }

    if (isRuleChar(rule)) {
      parts.push(
        col('[', Color.GRAY),
        col(
          rule.value
            .map((v) =>
              isRange(v)
