from typing import Any, Dict, Optional

from .grammar_graph_types import UnresolvedRule
from .print import print_graph_node


class GraphNodeMeta:
    __slots__ = ("stack_id", "path_id", "step_id")

    def __init__(self, stack_id: int, path_id: int, step_id: int):
        self.stack_id = stack_id
        self.path_id = path_id
        self.step_id = step_id

    @property
    def stackId(self) -> int:
        return self.stack_id

    @property
    def pathId(self) -> int:
        return self.path_id

    @property
    def stepId(self) -> int:
        return self.step_id

    def __repr__(self) -> str:
        return f"GraphNodeMeta({self.stack_id}, {self.path_id}, {self.step_id})"


class GraphNode:
    def __init__(
        self,
        rule: UnresolvedRule,
        meta: Optional[GraphNodeMeta],
        next_node: Optional["GraphNode"] = None,
    ):
        self.rule = rule
        if meta is None:
            raise ValueError("Meta is undefined")
        self.meta = meta
        self.next = next_node
        self.__id__: Optional[str] = None

    @property
    def id(self) -> str:
        if self.__id__ is None:
            self.__id__ = (
                f"{self.meta.stack_id},{self.meta.path_id},{self.meta.step_id}"
            )
        return self.__id__

    def print(self, opts: Dict[str, Any]) -> str:
        return print_graph_node(self)(opts)

    def __repr__(self) -> str:
        return f"GraphNode({self.id}, {self.rule!r})"

