import GBNF from '/workspace/reference_implementation/index.ts';

const mine = JSON.parse(readFileSync('/tmp/parity/reference_fixtures.json', 'utf8'));
const ser = (r: any) => (r.value === undefined ? { type: r.type } : { type: r.type, value: r.value });
const describe = (e: any) => ({ error: e?.name ?? 'Error', message: String(e?.message ?? e) });

const buildCase = (grammar: string, inputs: string[], sequences: string[][]) => {
  const c: any = { grammar };
  let state;
  try {
    state = GBNF(grammar);
    c.initialRules = [...state].map(ser);
    c.size = state.size;
  } catch (e) { c.initialError = describe(e); return c; }
  c.inputs = inputs.map((text) => {
    try { const s = GBNF(grammar, text); return { input: text, rules: [...s].map(ser), size: s.size }; }
    catch (e) { return { input: text, ...describe(e) }; }
  });
  c.sequences = sequences.map((chunks) => {
    const steps: any[] = [];
    try { let s = GBNF(grammar); for (const chunk of chunks) { s = s.add(chunk); steps.push({ chunk, rules: [...s].map(ser), size: s.size }); } }
    catch (e) { steps.push(describe(e)); }
    return { chunks, steps };
  });
  return c;
};

